WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[2] = { title = "Sharptalon's Claw", description = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.  Senani Thunderheart at the Splintertree Post will no doubt be interested in seeing this trophy as proof of your deeds.", objectives = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[5] = { title = "Jitters' Growling Gut", description = "I've been stuck hiding in this ghost town for weeks, and I haven't eaten anything but grubs and weeds!  I need some decent food, and I'm willing to trade well for it.\n\nBring me a feast and I'll pay you handsomely.\n\nI heard Chef Grual at the Scarlet Raven Tavern in Darkshire makes very good Dusky Crab Cakes...", objectives = "Speak with Chef Grual.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[6] = { title = "Bounty on Garrick Padfoot", description = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!\n\nBut be wary, $N.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", objectives = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7] = { title = "Kobold Camp Cleanup", description = "Your first task is one of cleansing, $N.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", objectives = "Kill 10 Kobold Vermin, then return to Marshal McBride.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[8] = { title = "A Rogue's Deal", description = "Hey, mate! Do a favor for a young man who's been fighting more than his fair share of mindless zombies and spiders?\n\nI got this here letter that needs to go to Brill... to an innkeeper named Renee something-or-other. Don't really matter none what her last name is.\n\nAnyway, it's a nice cozy little place full of victims of the plague trying to make their way in the world. And it be a great spot for you to rest too if the need arises. You should check it out... you do and I'll pay you well.", objectives = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[9] = { title = "The Killing Fields", description = "Look at what has happened to this place!  These lands were once occupied by good farm folk.  But the damned thieves have driven them all off.  Not me, though!  But it seems some Harvest Watchers have taken over the fields.\n\nIf you're up for the work, I'd like you to go out and kill twenty of them.  Come back when you're done for your pay.  If you finish up with the ones in my field, clear them from the neighboring fields as well.", objectives = "Farmer Saldean wants you to kill 20 Harvest Watchers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[10] = { title = "The Scrimshank Redemption", description = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?\n\nI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod.", objectives = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[11] = { title = "Riverpaw Gnoll Bounty", description = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east.\n\nThe Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.", objectives = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[12] = { title = "The People's Militia", description = "The People's Militia has but one goal:  To defend the lands of Westfall and return peace to our surroundings.  Unfortunately, the price of peace is often blood. \n\nOne of my scouts has brought word of a band of Defias Trappers wreaking havoc nearby.  I have reports of Defias Trapper sightings near the Jangolode Mine to the Northwest as well as at the Molsen Farm and Furlbrow's Pumpkin Farm. If you seek to join our ranks, slay 15 Defias Trappers and 15 Defias Smugglers then return to me.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[13] = { title = "The People's Militia", description = "A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, $n, and make the Light's presence known in Westfall.\n\nThe Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[14] = { title = "The People's Militia", description = "Some Defias have eluded us.  My most trusted scout reports that these Defias have been looting and pillaging the countryside, all the way into Southern Westfall.  We believe they are hiding out in the Dagger Hills, plotting their next move.   Slay the wretches in the name of The People's Militia.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[15] = { title = "Investigate Echo Ridge", description = "$N, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.\n\nGo to the mine and remove them.  We know there are at least 10.  Kill them, see if there are more, then report back to me.", objectives = "Kill 10 Kobold Workers, then report back to Marshal McBride.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[16] = { title = "Give Gerard a Drink", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[17] = { title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[18] = { title = "Brotherhood of Thieves", description = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.\n\nI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", objectives = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[19] = { title = "Tharil'zun", description = "Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep.  The leader of the Outrunners is an orc named Tharil'zun--we want this orc.  Bring me the head of Tharil'zun!", objectives = "Bring Tharil'zun's Head to Marshal Marris in Redridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[20] = { title = "Blackrock Menace", description = "The Blackrock orcs have travelled from the Burning Steppes and claimed Stonewatch Keep to the north.  From there they maraud the areas north of Lakeshire and keep its citizens in town, penned like cattle.\n\nHelp rid Lakeshire of this menace.  Kill these Blackrock orcs and bring me ten of their Battleworn Axes as proof.\n\nAnd although Blackrocks threaten us from the north, we've received reports of more in the southeastern pocket of Redridge.  If you find any there, then they too should be hunted.", objectives = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[21] = { title = "Skirmish at Echo Ridge", description = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, $N.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", objectives = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[22] = { title = "Goretusk Liver Pie", description = "The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!", objectives = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[23] = { title = "Ursangous's Paw", description = "The paw of the mighty bear Ursangous is your trophy for this part of the Ashenvale Hunt.  On the paw is a small quarter-crescent emblem; the significance of the emblem remains a mystery.\n\nThe paw should be brought to Senani Thunderheart in Splintertree Post to prove that you have bested the mighty creature and completed this portion of the hunt.", objectives = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[24] = { title = "Shadumbra's Head", description = "The once swift Shadumbra now lies still as you claim victory over it.  The head of the slain nightsaber is a fitting trophy for this fight of the Ashenvale Hunt.  Senani Thunderheart at Splintertree Post will want to see such a trophy to award you credit for this part of the Ashenvale Hunt.", objectives = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[25] = { title = "Stonetalon Standstill", description = "If you want to be useful, then why don't you do something about the situation near Talondeep Path?\n\nThe transports between Ashenvale and Stonetalon are at a standstill because of the lake coming alive and attacking anything that gets close... which means anyone on the path.  What'd be even more useful than just putting the hammer down on the water elementals there is someone scouting the gazebo on Mystral Lake - the one that has a solid view of the Alliance outpost there.\n\nYou up for being useful?", objectives = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.\n\nScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.\n\nReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[26] = { title = "A Lesson to Learn", description = "$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[27] = { title = "A Lesson to Learn", description = "$N, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[28] = { title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, $N.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[29] = { title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, $N.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[30] = { title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[31] = { title = "Aquatic Form", description = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.", objectives = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[32] = { title = "Rise of the Silithid", description = "Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.\n\nI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.\n\nZil lives in a house on the second tier of the Drag in Orgrimmar.", objectives = "Take the report to Zilzibin Drumlore in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[33] = { title = "Wolves Across the Border", description = "I hate those nasty timber wolves!  But I sure like eating wolf steaks...  Bring me tough wolf meat and I will exchange it for something you'll find useful.\n\nTough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.", objectives = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[34] = { title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", objectives = "Martie Jainrose of Lakeshire wants you to kill Bellygrub.  Bring her his tusk as proof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[35] = { title = "Further Concerns", description = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nBring me his report.", objectives = "Marshal Dughan wants you to speak with Guard Thomas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[36] = { title = "Westfall Stew", description = "I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.  \n \nMaybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.", objectives = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[37] = { title = "Find the Lost Guards", description = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.", objectives = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[38] = { title = "Westfall Stew", description = "Help me make some Westfall Stew!  Come back with the following ingredients: \n \n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra", objectives = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[39] = { title = "Deliver Thomas' Report", description = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.\n\nI know we don't have many troops to spare, but hopefully Dughan can find someone.", objectives = "Report to Marshal Dughan in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[40] = { title = "A Fishy Peril", description = "$N, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, $N, speak to Dughan and persuade him to send more troops to the east!", objectives = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[45] = { title = "Discover Rolf's Fate", description = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...", objectives = "Search the murloc village for Rolf, or signs of his death.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[46] = { title = "Bounty on Murlocs", description = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.", objectives = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[47] = { title = "Gold Dust Exchange", description = "The Kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.", objectives = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire.  Gold Dust is gathered from Kobolds in Elwynn Forest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[48] = { title = "Sweet Amber", description = "In the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", objectives = "Bring Holy Spring Water to Grimbooze Thunderbrew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[49] = { title = "Sweet Amber", description = "Amber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", objectives = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[50] = { title = "Sweet Amber", description = "I'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", objectives = "Grimbooze Thunderbrew wants Truesilver.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[51] = { title = "Sweet Amber", description = "Not yet filtered but freshly distilled\nLike unseeded land waiting there tilled.\nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", objectives = "Bring a Sycamore Branch to Grimbooze Thunderbrew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[52] = { title = "Protect the Frontier", description = "Hail, $N.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.", objectives = "Kill 8 Prowlers and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[53] = { title = "Sweet Amber", description = "Mellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", objectives = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[54] = { title = "Report to Goldshire", description = "$N, you are a $c with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.", objectives = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[55] = { title = "Morbent Fel", description = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...\n\nUse Morbent's Bane against him.  It will render his protective magics powerless.\n\nSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!", objectives = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[56] = { title = "The Night Watch", description = "As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.\n\nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[57] = { title = "The Night Watch", description = "$N, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[58] = { title = "The Night Watch", description = "The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, $N.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[59] = { title = "Cloth and Leather Armor", description = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, $N, use it in the defense of Elwynn.\n\nThe Eastvale Logging Camp is beyond Guard Thomas' post to the east.", objectives = "Give Sara Timberlain the Stormwind Armor Marker.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[60] = { title = "Kobold Candles", description = "Hello, $ggood sir:my lady;!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines ... the Fargodeep mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.", objectives = "Bring 8 Large Candles to William Pestle in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[61] = { title = "Shipment to Stormwind", description = "My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.\n\nI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.", objectives = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[62] = { title = "The Fargodeep Mine", description = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.", objectives = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[63] = { title = "Call of Water", description = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.\n\nTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.\n\nBring me proof the task is done, and I will reward you with your totem.", objectives = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[64] = { title = "The Forgotten Heirloom", description = "It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!", objectives = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[65] = { title = "The Defias Brotherhood", description = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.", objectives = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[66] = { title = "The Legend of Stalvan", description = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.\n\nAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.\n\nSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.", objectives = "Seek out the Clerk Daltry in the Darkshire Town Hall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[67] = { title = "The Legend of Stalvan", description = "Stalvan, eh?  Let me check the town registry.\n\nStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!\n\nDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.", objectives = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[68] = { title = "The Legend of Stalvan", description = "You find a Dusty Unsent Letter in the old footlocker.", objectives = "Take the Dusty Unsent Letter to Clerk Daltry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[69] = { title = "The Legend of Stalvan", description = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, $N.", objectives = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[70] = { title = "The Legend of Stalvan", description = "The name Stalvan rings a bell.  I remember now.\n\nMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.\n\nIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.", objectives = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[71] = { title = "Report to Thomas", description = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.", objectives = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[72] = { title = "The Legend of Stalvan", description = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.", objectives = "Search through the packed up possessions for a clue.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[74] = { title = "The Legend of Stalvan", description = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.", objectives = "The Torn Journal page you discovered provides your next clue.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[75] = { title = "The Legend of Stalvan", description = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. \n\nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.", objectives = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[76] = { title = "The Jasperlode Mine", description = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.", objectives = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[77] = { title = "A Sticky Situation", description = "I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.\n\nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.", objectives = "Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[78] = { title = "The Legend of Stalvan", description = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.", objectives = "Take the Faded Journal Page to Tavernkeep Smitts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[79] = { title = "The Legend of Stalvan", description = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!", objectives = "Take the muddy page to Commander Ebonlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[80] = { title = "The Legend of Stalvan", description = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.\n\nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.", objectives = "Show Clerk Daltry the Bloodstained Journal Page.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[81] = { title = "Ripple Delivery", description = "I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome.\n\nNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.", objectives = "Deliver the barrel to Dran Droffers in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[82] = { title = "Noxious Lair Investigation", description = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!", objectives = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[83] = { title = "Red Linen Goods", description = "The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me red linen bandanas and I'll use them to fashion something for you.\n\nDefias gang members have camps pocketed throughout Elwynn.", objectives = "Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[84] = { title = "Back to Billy", description = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!", objectives = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[85] = { title = "Lost Necklace", description = "I lost my necklace, and think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure vineyards east of here. \n\nGet my necklace back for me, and you'll warm an old widow's heart.", objectives = "Speak with Billy Maclure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[86] = { title = "Pie for Billy", description = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.", objectives = "Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[87] = { title = "Goldtooth", description = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run into the mine.  Go find that kobold and you'll find the necklace, I swear!", objectives = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[88] = { title = "Princess Must Die!", description = "The Brackwells have a prize-winning pig, Princess.  The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nSo before she comes to our fields...Princess must die!  Bring me her collar as proof of the deed and I'll give you something for your time!\n\nPrincess is usually over at the Brackwell Pumpkin Patch, to the east and beyond the Maclure farm.  Get her before she gets hungry and comes back here!", objectives = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[89] = { title = "The Everstill Bridge", description = "During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire.\n\nNow we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, $N, I'll make sure you're rewarded. \n\nNow let's get to work!", objectives = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[90] = { title = "Seasoned Wolf Kabobs", description = "Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.", objectives = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[91] = { title = "Solomon's Law", description = "An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business.\n\nMorganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death.\n\nThese vile gnolls must be killed!\n\nTurn in 10 Shadowhide Pendants to me, and you shall be rewarded.", objectives = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[92] = { title = "Redridge Goulash", description = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", objectives = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[93] = { title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them.\n\nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river. ", objectives = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[94] = { title = "A Watchful Eye", description = "My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.\n\nBut to study his thoughts ... I require further aid.\n\nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower.\n\nWhen this is done, the power of Azora will grant visions of Morganth's future plans.", objectives = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[95] = { title = "Sven's Revenge", description = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn.", objectives = "Go to Sven's Farm and find what was buried behind the old stump.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[96] = { title = "Call of Water", description = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.", objectives = "Bring the Shard of Water to Islen Waterseer in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[97] = { title = "The Legend of Stalvan", description = "Let Commander Ebonlocke know immediately that the handwriting matched, $N!  Her suspicions were correct!", objectives = "Report the news to Commander Ebonlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[98] = { title = "The Legend of Stalvan", description = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, $C, and execute Stalvan, once and for all.\n\nWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.", objectives = "Kill Stalvan Mistmantle and show Madame Eva his family ring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[99] = { title = "Arugal's Folly", description = "As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy.\n\nMy knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen.\n\nI need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, $N.", objectives = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[100] = { title = "Call of Water", description = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.", objectives = "Speak to the Minor Manifestation of Water in Silverpine Forest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[101] = { title = "The Totem of Infliction", description = "As the mystical taint creeps through the forest, the need for self-protection is undeniable, $N.  The winds whisper to me and they speak of a great danger which waits patiently for you in the near future.\n\nIf you wish to protect yourself, noble $c, bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", objectives = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[102] = { title = "Patrolling Westfall", description = "Stormwind has abandoned us.  A foul wind of depravity rustles through the plains of Westfall.  This was my homeland and I will not turn my back on the citizens who choose to remain here.  We, the former farmers, shall make our stand.\n\nYour task, should you choose to accept, is to patrol the grasslands of Westfall.  Track down and slay the vile Gnolls that seem to be working in conjunction with the Deadmines thieves. Bring me eight Gnoll Paws and I will reward your bravery.", objectives = "Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[103] = { title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me 5 flasks of oil from the Harvest Monsters.", objectives = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[104] = { title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[105] = { title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nYou may have noticed a summoning crystal inside the watchtowers you marked.  We believe these feed the lich power needed to dominate the city.  You must take down all four of them; destroying one will no doubt summon more of the lich's troops.  If all four are down, the lich itself should arise to defend the heart of the city.\n\nDestroy the lich, $N, and bring me a shard from its phylactery as proof!", objectives = "Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[106] = { title = "Young Lovers", description = "Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face!\n\nPlease, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.", objectives = "Give Maybell's Love Letter to Tommy Joe Stonefield.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[107] = { title = "Note to William", description = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.", objectives = "Take Gramma Stonefield's Note to William Pestle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[109] = { title = "Report to Gryan Stoutmantle", description = "Looks to me you've seen quite a bit of combat in your time, $c.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.", objectives = "Talk to Gryan Stoutmantle.  He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[110] = { title = "Insect Part Analysis", description = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.", objectives = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[111] = { title = "Speak with Gramma", description = "Please, $N, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.", objectives = "Speak with Gramma Stonefield.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[112] = { title = "Collecting Kelp", description = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the Liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.", objectives = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[113] = { title = "Insect Part Analysis", description = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!", objectives = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[114] = { title = "The Escape", description = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.", objectives = "Take the Invisibility Liquor to Maybell Maclure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[115] = { title = "Shadow Magic", description = "The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict.\n\nFind and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!", objectives = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[116] = { title = "Dry Times", description = "I find myself in quite a pinch here, $N.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", objectives = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[117] = { title = "Thunderbrew", description = "Hurry, my friend, move with haste \nIn order for our rich lager to taste \nMore like beer and less like stew, \nHops are needed to make the brew.", objectives = "Bring Grimbooze Thunderbrew 5 hops to complete his special brew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[118] = { title = "The Price of Shoes", description = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.", objectives = "Take Verner's Note to Smith Argus in Goldshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[119] = { title = "Return to Verner", description = "Ok, I'll give him his 50 horseshoes...\n\nHere they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!", objectives = "Return to Verner Osgood in Redridge.  Give him the Crate of Horseshoes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[120] = { title = "Messenger to Stormwind", description = "These are trying times, $c.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. \n\nNow make haste!", objectives = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[121] = { title = "Messenger to Stormwind", description = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, $c!", objectives = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[122] = { title = "Underbelly Scales", description = "I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you.\n\nBlack dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.", objectives = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[123] = { title = "The Collector", description = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Dughan in Goldshire.", objectives = "Go to Marshal Dughan in Goldshire and give him The Collector's Schedule", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[124] = { title = "A Baying of Gnolls", description = "As if the attacking orcs weren't enough!  Now I have gnoll brutes and mystics prowling along the ridge north of my stable, taking my horses when they stray...\n\nIf you can get rid of those gnolls, my horses and I would be very grateful.", objectives = "Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[125] = { title = "The Lost Tools", description = "I could really use a hand here, $N.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, $N, and I'll make it worth your while.", objectives = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[126] = { title = "Howling in the Hills", description = "$N, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader.\n\nKill Yowler and send his pack scattering!  Bring me his paw as proof.\n\nAnd be careful, this gnoll is their leader for a reason.  He is no Mongrel...", objectives = "Bring Yowler's Paw to Verner Osgood in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[127] = { title = "Selling Fish", description = "Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low!\n\nBring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!", objectives = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[128] = { title = "Blackrock Bounty", description = "The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes.\n\nMagistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.", objectives = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[129] = { title = "A Free Lunch", description = "Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me.\n\nSo if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.", objectives = "Bring Parker's lunch to Guard Parker.  He patrols the road leading to Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[130] = { title = "Visit the Herbalist", description = "Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town.\n\nBut when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...", objectives = "Speak with the Redridge Herbalist, Martie Jainrose.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[131] = { title = "Delivering Daffodils", description = "Here is your bouquet.  I chose Daffodils for you.  They're my favorite!", objectives = "Give Darcy the Daffodil Bouquet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[132] = { title = "The Defias Brotherhood", description = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle.  It explains as much as I know on the subject.", objectives = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[133] = { title = "Ghoulish Effigy", description = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!\n\nI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.\n\nGet the ribs for me, and I will repay you with some coin.", objectives = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[134] = { title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, $N, retrieve this crate for me for I miss it sorely.", objectives = "Return Abercrombie's Crate to Abercrombie.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[135] = { title = "The Defias Brotherhood", description = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.", objectives = "Take Wiley's Note to Mathias Shaw in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[136] = { title = "Captain Sander's Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", objectives = "Find Captain Sanders' footlocker and search it for the next clue.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[138] = { title = "Captain Sander's Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", objectives = "Find the old barrel near the ruined chimney and search it for your next clue.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[139] = { title = "Captain Sander's Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", objectives = "Search the empty jug next to the windmill for the next clue.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[140] = { title = "Captain Sander's Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sander's treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", objectives = "Locate Captain Sanders' chest and open it for your reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[141] = { title = "The Defias Brotherhood", description = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!", objectives = "Take Shaw's report to Gryan Stoutmantle in Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[142] = { title = "The Defias Brotherhood", description = "We need to discover the location of the Defias hideout.  $N, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.", objectives = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[143] = { title = "Messenger to Westfall", description = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.\n\nTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.", objectives = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[144] = { title = "Messenger to Westfall", description = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.\n\nTake this response to your master in Redridge, $c.  And let him know that my heart is heavy with the loss of good men.", objectives = "Return to Magistrate Solomon with Gryan Stoutmantle's response.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[145] = { title = "Messenger to Darkshire", description = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.", objectives = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[146] = { title = "Messenger to Darkshire", description = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.\n\nTake this letter of response to your Master in Lakeshire.", objectives = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[147] = { title = "Manhunt", description = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.", objectives = "Find and kill \"the Collector\"  then return to Marshal Dughan with The Collector's Ring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[148] = { title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.", objectives = "Speak with Madame Eva.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[149] = { title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", objectives = "Bring the Spectral Comb to Blind Mary.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[150] = { title = "Murloc Poachers", description = "Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake!\n\nHunt murlocs!  Bring me eight of their fins and I might have something for you...", objectives = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[151] = { title = "Poor Old Blanchy", description = "Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.\n\nI bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.", objectives = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[152] = { title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", objectives = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[153] = { title = "Red Leather Bandanas", description = "The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear.\n\nBring me 15 of these Bandanas and I'll see to it you are rewarded.", objectives = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[154] = { title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[155] = { title = "The Defias Brotherhood", description = "So Stoutmantle sends a scrawny $r like you to protect me?  Guess you'll have to do.  Better bring some friends too. \n\nYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.", objectives = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood.  Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[156] = { title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nRot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!\n\nThe Raven Hill Cemetery and the Tranquil Gardens are both lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.", objectives = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[157] = { title = "Deliver the Thread", description = "Here is your thread, $N.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", objectives = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[158] = { title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, $N.  These nights get cold, and I need that drink to put fire in my veins again!", objectives = "Speak with Tavernkeep Smitts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[159] = { title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", objectives = "Bring the Zombie Juice to Abercrombie at his shack.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[160] = { title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[161] = { title = "A Dark Threat Looms", description = "If my suspicions are correct, this is some type of explosive powder.  This must be analyzed by an explosives expert so we know just what we're dealing with here.  Ashlan Stonesmirk was assigned to the regiment guarding Dun Modr and the Thandol Span.  I need you to make a grave and perilous journey, $N.\n\nTravel through the Algaz Gate, follow the road through the Wetlands and seek out Stonesmirk in Dun Modr.  Heed my advice: stick to the roads and stop for nothing!", objectives = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[162] = { title = "Rise of the Silithid", description = "I urge you to take this report to someone who has working knowledge in this kind of thing.\n\nI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.\n\nLast I heard, she was residing in the Temple of the Moon, located in Darnassus.", objectives = "Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[163] = { title = "Raven Hill", description = "Something's amiss at Raven Hill, $n. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows.\n\nIf, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.", objectives = "Find out what is haunting Raven Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[164] = { title = "Deliveries to Sven", description = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.\n\nUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?", objectives = "Deliver the supplies to Sven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[165] = { title = "The Hermit", description = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.", objectives = "Check on the old man in the shack near Raven Hill cemetery.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[166] = { title = "The Defias Brotherhood", description = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.", objectives = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[167] = { title = "Oh Brother. . .", description = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.", objectives = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[168] = { title = "Collecting Memories", description = "Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.", objectives = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[169] = { title = "Wanted: Gath'Ilzogg", description = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.", objectives = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[170] = { title = "A New Threat", description = "I hope you're here to lend us a hand, $c. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, $g lad : lass;, and we need strong arms to help drive the troggs back.", objectives = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[171] = { title = "A Warden of the Alliance", description = "You have been so very kind to me, $N.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I don't wanna be sad about what's happened to me and all - my folks always told me to rise above anything bad that happens.  You know, when I grow up I wanna be a hero... just like you.\n\nI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!", objectives = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[172] = { title = "Ambushed In The Forest", description = "Lord Ebonlocke sent me to Stormwind to represent Darkshire at the recent council of the House of Nobles. I was tasked with requesting military aid in light of the undead infestation which has taken over the forest.But on my way back a band of thieves ambushed me. I was forced to drive my cart to The Rotting Orchard in southern Duskwood.Before the thieves could rob me of my goods, a pack of ferocious Worgen overtook the thugs. Now I need you to retrieve my satchel from the chest in the wagon.", objectives = "Retrieve Ambassador Berrybuck's satchel and bring it back to him in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[173] = { title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.", objectives = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[174] = { title = "Look To The Stars", description = "My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest.\n\nBring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.", objectives = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[175] = { title = "Look To The Stars", description = "According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[176] = { title = "Wanted:  \"Hogger\"", description = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should bring proof of Hogger's demise to Marshal Dughan in Goldshire.", objectives = "Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[177] = { title = "Look To The Stars", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", objectives = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[178] = { title = "Theocritus' Retrieval", description = "<You hear a disembodied voice...>\n\nDo not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth.\n\nThrough months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success.\n\nBring me this pendant and I will reward you for the service.", objectives = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[179] = { title = "Dwarven Outfitters", description = "What do we have here? You look as though you might need something to keep your hands warm, hm?\n\nI'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however.\n\nI need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?", objectives = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[180] = { title = "Wanted: Lieutenant Fangore", description = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.", objectives = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[181] = { title = "Look To The Stars", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", objectives = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[182] = { title = "The Troll Cave", description = "My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances.\n\nFrom what I've seen, the trolls aren't well situated here in Coldridge Valley--mostly the southern cave. I'd say that the army will not be necessary. A few strong arms should be more than enough.\n\nPerhaps you'd like to assist in this endeavor? I have the authority to offer compensation for your help.", objectives = "Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[183] = { title = "The Boar Hunter", description = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.", objectives = "Talin Keeneye would like you to kill 12 Small Crag Boars.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[184] = { title = "Furlbrow's Deed", description = "This is the deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...", objectives = "Bring Furlbrow's Deed to Farmer Furlbrow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[185] = { title = "Tiger Mastery", description = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.", objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[186] = { title = "Tiger Mastery", description = "You are learning, $c.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out.", objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[187] = { title = "Tiger Mastery", description = "Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence.\n\nElder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat.", objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[188] = { title = "Tiger Mastery", description = "Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no $r has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment.\n\nTracking her down will be no easy task.", objectives = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[189] = { title = "Bloodscalp Ears", description = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... $n, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.", objectives = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[190] = { title = "Panther Mastery", description = "If you want to be a part of the hunt with this crack group Hemet has assembled, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start.\n\nTracking them down is only half the challenge...", objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[191] = { title = "Panther Mastery", description = "Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers.\n\nThose big boys are tougher.  They're not as easy as the young ones you were killing earlier.", objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[192] = { title = "Panther Mastery", description = "Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts.\n\nIf you think they are hard to track, wait until you attempt to slay one....", objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[193] = { title = "Panther Mastery", description = "You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera.\n\nBring me the Fang of Bhag'thera and you'll have earned my respect!", objectives = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[194] = { title = "Raptor Mastery", description = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.", objectives = "Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[195] = { title = "Raptor Mastery", description = "Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!", objectives = "Hemet Nesingwary wants you to kill 10 Lashtail Raptors.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[196] = { title = "Raptor Mastery", description = "Let's see how you handle this next challenge.  There is a cagey breed of raptor out there.  We call them Jungle Stalkers.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.  Kill 10 Jungle Stalkers and I'll tip you off to the best hunting yet.", objectives = "Hemet Nesingwary wants you to kill 10 Jungle Stalkers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[197] = { title = "Raptor Mastery", description = "Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill.  Ajeck here calls this wily raptor Tethis.\n\nIf you want to prove yourself a true master, kill Tethis and bring me his talon.  It would be a feat that no other big game hunter has accomplished.", objectives = "Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[198] = { title = "Supplies to Private Thorsen", description = "Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution.", objectives = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[199] = { title = "A Dark Threat Looms", description = "You take a sample of the strange smelling powder.", objectives = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[200] = { title = "Bookie Herod", description = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there.", objectives = "Find Bookie Herod's Records.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[201] = { title = "Investigate the Camp", description = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti. Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary was one of the hunters there? He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, $n, see what they're about?", objectives = "Find the hunters' camp and report its location to Krazek in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[202] = { title = "Colonel Kurzen", description = "You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, $N.  My hope, and the fate of my men, go with you.", objectives = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[203] = { title = "The Second Rebellion", description = "We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.", objectives = "Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[204] = { title = "Bad Medicine", description = "To have a chance against Kurzen, we need his healing support neutralized.  He has gathered around him a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts.\n\nWe need those remedies to cure our own people, and we need a sample of those extracts to study so we can make our own remedies.  Search the Kurzen Compound for both - his Medicine Men will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.", objectives = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[205] = { title = "Troll Witchery", description = "While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.", objectives = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[206] = { title = "Mai'Zoth", description = "Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.", objectives = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[207] = { title = "Kurzen's Mystery", description = "Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda.", objectives = "Find the 4 tablets and bring their legends back to Brother Nimetz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[208] = { title = "Big Game Hunter", description = "$N, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bag'thera and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here.  I've had my sights on him for quite some time now.  Kill King Bangalash and your hunting prowess is proven to be second to none.", objectives = "Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[209] = { title = "Skullsplitter Tusks", description = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!", objectives = "Acquire 18 Skullsplitter Tusks and return them to Kebok.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[210] = { title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.", objectives = "Bring Krazek's Crock Pot to Krazek the goblin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[211] = { title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nYou may have noticed a summoning crystal inside the watchtowers you marked.  We believe these feed the lich power needed to dominate the city.  You must take down all four of them; destroying one will no doubt summon more of the lich's troops.  If all four are down, the lich itself should arise to defend the heart of the city.\n\nDestroy the lich, $N, and bring me a shard from its phylactery as proof!", objectives = "Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[212] = { title = "A Meal Served Cold", description = "One of my most famous dishes is Chilled Basilisk in Lime Vinaigrette.  But the problem is... the meat is impossible to keep fresh, and I must serve the dish tonight for a noble's birthday!\n\nSo if you can bring me a Chilled Basilisk Haunch from a freshly-killed Cold Eye Basilisk, quickly, then I will owe you a king's feast!\n\nCold Eye Basilisks are known to roam along the beach dunes of northwestern Stranglethorn, so you have much traveling to do.  And be swift!", objectives = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.\n\n<You must not release your spirit to succeed in this quest.>", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[213] = { title = "Hostile Takeover", description = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.", objectives = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[214] = { title = "Red Silk Bandanas", description = "It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, $N.", objectives = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[215] = { title = "Jungle Secrets", description = "Thank you for saving me, $N.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.", objectives = "Speak with Lieutenant Doren at the Rebel Camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[216] = { title = "Between a Rock and a Thistlefur", description = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n$N, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", objectives = "Take down 12 Thistlefur Avengers and 12 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village.  Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[217] = { title = "In Defense of the King's Lands", description = "$N, our scouts have identified the leader of this recent Trogg incursion.  It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug.  Grawmug is heavily guarded, however.  Two of his most elite guards, Gnasher and Brawler, never leave his side.\n\nIf you feel yourself worthy, $N, I want you to lead the assassination mission on Grawmug and his two thugs.  With the Trogg leadership dead, we just might stand a chance at pushing these beasts back into the ground.", objectives = "Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[218] = { title = "The Stolen Journal", description = "My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?", objectives = "Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[219] = { title = "Missing In Action", description = "At last, friends of the Alliance!\n\nHelp... please... \n\nThe last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly.\n\nI'll need help getting back to town... please... you're my last hope...", objectives = "Protect Corporal Keeshan on the journey back to Redridge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[220] = { title = "Call of Water", description = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.\n\nGo now and find her. We shall meet again some day.", objectives = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[221] = { title = "Worgen in the Woods", description = "You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.\n\nOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.\n\nBe on your guard.", objectives = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[222] = { title = "Worgen in the Woods", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", objectives = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[223] = { title = "Worgen in the Woods", description = "Here you go, $n. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", objectives = "Bring Calor's note to Jonathan Carevin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[224] = { title = "In Defense of the King's Lands", description = "We need to protect the Loch, $N!  With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front.  Troggs are tunneling up from every crevice!  The Trogg infestation poses the largest threat to Ironforge.  These disgusting mutants must be destroyed.\n\nWe need you, brave adventurer, to venture forth and lay waste to the Trogg threat.  Slay 10 Stonesplinter Troggs and 10 Stonesplinter Scouts and report back.", objectives = "Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[225] = { title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", objectives = "Speak with Sirra Von'Indi in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[226] = { title = "Wolves at Our Heels", description = "Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work!\n\nBut if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.", objectives = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[227] = { title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", objectives = "Speak with Commander Althea Ebonlocke in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[228] = { title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[229] = { title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", objectives = "Speak with Watcher Sarah Ladimore in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[230] = { title = "Sven's Camp", description = "Digging through the mound, you find a small, dirt-stained book.\n\nThe book has no title, but...it has information Sven would like to know.", objectives = "Bring the Book from Sven's Farm to Sven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[231] = { title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, $n.", objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[232] = { title = "Errand for Apothecary Zinge", description = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.\n\nApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.", objectives = "Take the purchase order to Alessandro Luca in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[233] = { title = "Coldridge Valley Mail Delivery", description = "Hm, I don't suppose you'd be willing to do a favor for me, $g lad : lass;? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?", objectives = "Deliver the stack of letters to Talin Keeneye.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[234] = { title = "Coldridge Valley Mail Delivery", description = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.", objectives = "Deliver the letter to Grelin Whitebeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[235] = { title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[237] = { title = "In Defense of the King's Lands", description = "Mountaineer Cobbleflint had nothing but good things to say about you, $r.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front.\n\nSet forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.", objectives = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[238] = { title = "Errand for Apothecary Zinge", description = "The kit is ready, $n.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.\n\nWell, don't just stand there.  Such is the life of a simple courier, yes?", objectives = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[239] = { title = "Westbrook Garrison Needs Help!", description = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.", objectives = "Go to the Westbrook Garrison and speak with Deputy Rainer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[240] = { title = "Return to Jitters", description = "And here we are - \"Crab\" Cakes ala Grual!", objectives = "Return to Jitters with the Dusky Crab Cakes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[243] = { title = "Into the Field", description = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.\n\nIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.\n\nReturn to me only when you are successful.", objectives = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[244] = { title = "Encroaching Gnolls", description = "Hail, $c.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here.\n\nLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage.\n\nFeldon's usually inspecting the area south of the bridge to Lakeshire.", objectives = "Report to Deputy Feldon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[245] = { title = "Eight-Legged Menaces", description = "Hail, $c. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire.\n\nI hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs.\n\nOh, and a word of advice, you'll want to avoid their venom if you can.", objectives = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[246] = { title = "Assessing the Threat", description = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, $N, and you will be rewarded.", objectives = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[247] = { title = "The Hunt Completed", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[248] = { title = "Looking Further", description = "I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery.\n\nTake another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep.\n\nFind a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.", objectives = "Climb the intact watch tower beside Stonewatch Keep.\n\nFind a suitable container to place the Glyph of Azora.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[249] = { title = "Morganth", description = "After much observation, I have discovered Morganth's plans.\n\nHe searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might.\n\nI am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth.\n\nDefeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.", objectives = "Defeat Morganth.\n\nBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[250] = { title = "A Dark Threat Looms", description = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.\n\nThat's why I need you, $N.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.", objectives = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[251] = { title = "Translate Abercrombie's Note", description = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.", objectives = "Bring the Letter to Ello to Sirra Von'Indi.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[252] = { title = "Translation to Ello", description = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.\n\nYou better bring the translated note back to Ello.\n\nAnd do so quickly, for I fear a doom already lumbers toward our town...", objectives = "Bring the Translated Letter to Lord Ello Ebonlocke", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[253] = { title = "Bride of the Embalmer", description = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.\n\nThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.\n\nHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.", objectives = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[254] = { title = "Digging Through the Dirt", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[255] = { title = "Mercenaries", description = "Two months just to hear from Ironforge that we'll be spared a handful of soldiers for our own defense, and another two months until they arrive! Bad enough that our town goes unprotected, but the excavation and the dam--the dam!--are open to attacks as well.\n\nI've no choice then, it seems. I'll need hired arms.\n\nHow about you? You seem a likely sort, $c. A group of ogres has set up camp on the northeast of the lake. Perhaps you could recruit some others and help remove the threat to our town?", objectives = "Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[256] = { title = "WANTED: Chok'sul", description = "By order of the Magistrate of Thelsamar:\n\nChok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary.\n\nMonetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death.\n\nChok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.", objectives = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[257] = { title = "A Hunter's Boast", description = "Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.\n\nA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge in fifteen minutes, I'll give you my bow or gun.\n\n<He looks you over dismissively.>\n\nIt seems you haven't much to lose, anyways.", objectives = "Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[258] = { title = "A Hunter's Challenge", description = "$nath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat.\n\nYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them. I'll give you just twelve minutes this time.\n\nDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!\n\nHave I ever related to you the story of how I received my famous scar? No? It was two years ago...", objectives = "Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[261] = { title = "Down the Scarlet Path", description = "I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.\n\nIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.\n\nDo this, and the Crusade will embrace you.", objectives = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[262] = { title = "The Shadowy Figure", description = "I must know who was that skulker in the shadows I saw the night my family was killed!\n\nPlease, $N, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!\n\nI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.", objectives = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[263] = { title = "In Defense of the King's Lands", description = "The Mountaineers tell me you are quite brave and capable, $N.  We need a $r like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned $c here, let's see what you can do.\n\nGo out and kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.  Let's see if you live up to your reputation, Trogg-Slayer.", objectives = "Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[264] = { title = "Until Death Do Us Part", description = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, $N! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!", objectives = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[265] = { title = "The Shadowy Search Continues", description = "Here is your book back, $N, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.\n\nAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.", objectives = "See if other townsfolk have clues about the shadowy figure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
